35	/**
36	 * Container for common test execution settings shared by all
37	 * all TestRunnerAction instances for the given test target.
38	 */
39	public final class TestTargetExecutionSettings {
40	
41	  private final CommandLine testArguments;
42	  private final String testFilter;
43	  private final int totalShards;
44	  private final int totalRuns;
45	  private final RunUnder runUnder;
46	  private final Artifact runUnderExecutable;
47	  private final Artifact executable;
48	  private final boolean runfilesSymlinksCreated;
49	  @Nullable private final Path runfilesDir;
50	  private final Runfiles runfiles;
51	  private final Artifact runfilesInputManifest;
52	  private final Artifact instrumentedFileManifest;
53	  private final boolean testRunnerFailFast;
54	  private final OS executionOs;
55	
56	  TestTargetExecutionSettings(
57	      RuleContext ruleContext,
58	      RunfilesSupport runfilesSupport,
59	      Artifact executable,
60	      Artifact instrumentedFileManifest,
61	      int shards,
62	      int runs)
63	      throws InterruptedException { // due to CommandLine.arguments
64	    Preconditions.checkArgument(TargetUtils.isTestRule(ruleContext.getRule()));
65	    Preconditions.checkArgument(shards >= 0);
66	    BuildConfigurationValue config = ruleContext.getConfiguration();
67	    TestConfiguration testConfig = config.getFragment(TestConfiguration.class);
68	
69	    CommandLine targetArgs = runfilesSupport.getArgs();
70	    testArguments =
71	        CommandLine.concat(targetArgs, ImmutableList.copyOf(testConfig.getTestArguments()));
72	
73	    totalShards = shards;
74	    totalRuns = runs;
75	    runUnder = config.getRunUnder();
76	    runUnderExecutable = getRunUnderExecutable(ruleContext);
77	
78	    this.testFilter = testConfig.getTestFilter();
79	    this.testRunnerFailFast = testConfig.getTestRunnerFailFast();
80	    this.executable = executable;
81	    this.runfilesSymlinksCreated = runfilesSupport.getRunfilesTree().isBuildRunfileLinks();
82	    this.runfilesDir = runfilesSupport.getRunfilesDirectory();
83	    this.runfiles = runfilesSupport.getRunfiles();
84	    this.runfilesInputManifest = runfilesSupport.getRunfilesInputManifest();
85	    this.instrumentedFileManifest = instrumentedFileManifest;
86	    this.executionOs =
87	        ConstraintConstants.getOsFromConstraints(ruleContext.getExecutionPlatform().constraints());
88	  }
89	
90	  @Nullable
91	  private static Artifact getRunUnderExecutable(RuleContext ruleContext) {
92	    TransitiveInfoCollection runUnderTarget = ruleContext.getRunUnderPrerequisite();
93	    return runUnderTarget == null
94	        ? null
95	        : runUnderTarget.getProvider(FilesToRunProvider.class).getExecutable();
96	  }
97	
98	  public Artifact getRunUnderExecutable() {
99	    return runUnderExecutable;
100	  }
101	
102	  public CommandLine getArgs() {
103	    return testArguments;
104	  }
105	
106	  public String getTestFilter() {
107	    return testFilter;
108	  }
109	
110	  public boolean getTestRunnerFailFast() {
111	    return testRunnerFailFast;
112	  }
113	
114	  public int getTotalShards() {
115	    return totalShards;
116	  }
117	
118	  public int getTotalRuns() {
119	    return totalRuns;
120	  }
121	
122	  public RunUnder getRunUnder() {
123	    return runUnder;
124	  }
125	
126	  public Artifact getExecutable() {
127	    return executable;
128	  }
129	
130	  /** @return whether or not the runfiles symlinks were created */
131	  public boolean getRunfilesSymlinksCreated() {
132	    return runfilesSymlinksCreated;
133	  }
134	
135	  /** @return the directory of the runfiles. */
136	  @Nullable
137	  public Path getRunfilesDir() {
138	    return runfilesDir;
139	  }
140	
141	  /** @return the runfiles for the test */
142	  public Runfiles getRunfiles() {
143	    return runfiles;
144	  }
145	
146	  /**
147	   * Returns the input runfiles manifest for this test.
148	   *
149	   * <p>This always returns the input manifest outside of the runfiles tree.
150	   *
151	   * @see com.google.devtools.build.lib.analysis.RunfilesSupport#getRunfilesInputManifest()
152	   */
153	  public Artifact getInputManifest() {
154	    return runfilesInputManifest;
155	  }
156	
157	  /**
158	   * Returns instrumented file manifest or null if code coverage is not
159	   * collected.
160	   */
161	  public Artifact getInstrumentedFileManifest() {
162	    return instrumentedFileManifest;
163	  }
164	
165	  public OS getExecutionOs() {
166	    return executionOs;
167	  }
168	
169	  public boolean needsShell() {
170	    if (getRunUnder() instanceof CommandRunUnder commandRunUnder) {
171	      String command = commandRunUnder.command();
172	      // --run_under commands that do not contain '/' are either shell built-ins or need to be
173	      // located on the PATH env, so we wrap them in a shell invocation. Note that we
174	      // shell-tokenize
175	      // the --run_under parameter and getCommand only returns the first such token.
176	      return !command.contains("/") && (!executionOs.equals(OS.WINDOWS) || !command.contains("\\"));
177	    } else {
178	      return false;
179	    }
180	  }
181	}
