100	  /**
101	   * {@link com.google.devtools.build.lib.skyframe.config.BuildConfigurationFunction} constructs
102	   * {@link BuildOptions} out of the options required by the registered fragments. We create and
103	   * register this fragment exclusively to ensure {@link StrictActionEnvOptions} is always
104	   * available.
105	   */
106	  @RequiresOptions(options = {StrictActionEnvOptions.class})
107	  public static class StrictActionEnvConfiguration extends Fragment {
108	    public StrictActionEnvConfiguration(BuildOptions buildOptions) {}
109	  }
