135	  public static final Function<BuildOptions, ActionEnvironment> SHELL_ACTION_ENV =
136	      (BuildOptions options) -> {
137	        if (options.hasNoConfig()) {
138	          return ActionEnvironment.EMPTY;
139	        }
140	        boolean strictActionEnv = options.get(StrictActionEnvOptions.class).useStrictActionEnv;
141	        OS os = OS.getCurrent();
142	        // TODO(ulfjack): instead of using the OS Bazel runs on, we need to use the exec platform,
143	        // which may be different for remote execution. For now, this can be overridden with
144	        // --shell_executable, so at least there's a workaround.
145	        PathFragment shellExecutable =
146	            getShellExecutableForOs(os, options.get(ShellConfiguration.Options.class));
147	
148	        TreeMap<String, String> env = new TreeMap<>();
149	
150	        // All entries in the builder that have a value of null inherit the value from the client
151	        // environment, which is only known at execution time - we don't want to bake the client env
152	        // into the configuration since any change to the configuration requires rerunning the full
153	        // analysis phase.
154	        if (!strictActionEnv) {
155	          env.put("LD_LIBRARY_PATH", null);
156	        }
157	
158	        if (strictActionEnv) {
159	          env.put("PATH", pathOrDefault(os, null, shellExecutable));
160	        } else if (os == OS.WINDOWS) {
161	          // TODO(ulfjack): We want to add the MSYS root to the PATH, but that prevents us from
162	          // inheriting PATH from the client environment. For now we use System.getenv even though
163	          // that is incorrect. We should enable strict_action_env by default and then remove this
164	          // code, but that change may break Windows users who are relying on the MSYS root being in
165	          // the PATH.
166	          String pathEnv = System.getenv("PATH");
167	          if (pathEnv != null) {
168	            pathEnv = platformToInternal(pathEnv);
169	          }
170	          env.put("PATH", pathOrDefault(os, pathEnv, shellExecutable));
171	        } else {
172	          // The previous implementation used System.getenv (which uses the server's environment),
173	          // and fell back to a hard-coded "/bin:/usr/bin" if PATH was not set.
174	          env.put("PATH", null);
175	        }
176	
177	        // Shell environment variables specified via options take precedence over the
178	        // ones inherited from the fragments. In the long run, these fragments will
179	        // be replaced by appropriate default rc files anyway.
180	        for (var envVar : options.get(CoreOptions.class).actionEnvironment) {
181	          switch (envVar) {
182	            case Converters.EnvVar.Set(String name, String value) -> env.put(name, value);
183	            case Converters.EnvVar.Inherit(String name) -> env.put(name, null);
184	            case Converters.EnvVar.Unset(String name) -> env.remove(name);
185	          }
186	        }
187	
188	        if (!BuildConfigurationValue.runfilesEnabled(options.get(CoreOptions.class))) {
189	          // Setting this environment variable is for telling the binary running
190	          // in a Bazel action when to use runfiles library or runfiles tree.
191	          // The downside is that it will discard cache for all actions once
192	          // --enable_runfiles changes, but this also prevents wrong caching result if a binary
193	          // behaves differently with and without runfiles tree.
194	          env.put("RUNFILES_MANIFEST_ONLY", "1");
195	        }
196	
197	        return ActionEnvironment.split(env);
198	      };
