662	  private Artifact internalCreateOutputArtifact(
663	      PathFragment rootRelativePath, Target target, OutputFile.Kind outputFileKind) {
664	    Preconditions.checkState(
665	        target.getLabel().getPackageIdentifier().equals(getLabel().getPackageIdentifier()),
666	        "Creating output artifact for target '%s' in different package than the rule '%s' "
667	            + "being analyzed",
